"""Generate C cases from explicitly authored selection-colour expectations."""
import argparse
from pathlib import Path
from selection_colour_cases import CASES

def literal(text):
    return '"'+''.join('\\%03o'%b if b < 32 or b >= 127 else
                       '\\'+chr(b) if chr(b) in '\\"' else chr(b)
                       for b in text.encode())+'"'

content = ('/* Specification/source-derived cases; not a captured XTerm oracle.\n'
           ' * Generated by tests/generate_selection_colour_cases.py. */\n'
           'static const struct { const char *name, *sequence, *reply; }\n'
           'selection_colour_cases[] = {\n'+
           ''.join('    {'+', '.join(map(literal, case))+'},\n' for case in CASES)+
           '};\n')
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--check', action='store_true')
args = parser.parse_args()
path = Path(__file__).with_name('selection_colour_cases.h')
if args.check:
    assert path.read_text(encoding='utf-8') == content, 'Regenerate '+path.name
else:
    path.write_text(content, encoding='utf-8')
print(f'{len(CASES)} authored selection-colour cases')
